(() => {
  const cap = 3000;
  return nodes.unread.output.map((it) => ({
    id: it.id,
    title: it.title,
    url: it.url,
    feed: it.feed && it.feed.title,
    category: it.feed && it.feed.category && it.feed.category.title,
    published_at: it.published_at,
    content: (it.content || '').slice(0, cap),
    truncated: (it.content || '').length > cap,
  }));
})()

compose.expr:
(() => {
  const items = nodes.unread.output;
  const total = nodes.count.output;
  const summaries = {};
  for (const s of nodes.summarize.output.summaries) summaries[s.id] = s.summary;
  const emoji = {
    finance: '\u{1F4B0}',
    investing: '\u{1F4C8}',
    quant: '\u{1F4C8}',
    economics: '\u{1F9EE}',
    'data science': '\u{1F4CA}',
    kids: '\u{1F9D2}',
  };
  const esc = (t) =>
    String(t == null ? '' : t)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  const order = [];
  const byCategory = {};
  for (const it of items) {
    const cat =
      (it.feed && it.feed.category && it.feed.category.title) || 'misc';
    if (!byCategory[cat]) { byCategory[cat] = []; order.push(cat); }
    byCategory[cat].push(it);
  }
  const header =
    '\u{1F4F0} Feeds \u2014 ' + items.length + ' shown (' + total + ' unread)';
  const parts = ['<b>' + header + '</b>'];
  const batch = [];
  let n = 0;
  for (const cat of order) {
    parts.push(
      '<h3>' + (emoji[cat.toLowerCase()] || '\u{1F9E9}') + ' ' + esc(cat) + '</h3>',
    );
    parts.push('<ol start="' + (n + 1) + '">');
    for (const it of byCategory[cat]) {
      n += 1;
      batch.push({
        n: n,
        id: it.id,
        title: it.title,
        url: it.url,
        feed: it.feed && it.feed.title,
        category: cat,
      });
      parts.push(
        '<li><a href="' + esc(it.url) + '">' + esc(it.title) + '</a> \u2014 <i>' +
          esc(it.feed && it.feed.title) + '</i><br>' +
          esc(summaries[it.id] || '') + '</li>',
      );
    }
    parts.push('</ol>');
  }
  parts.push(
    '<p>Reply with: <b>save 1 4</b> \u00b7 <b>summarize 7</b> \u00b7 <b>dismiss 2</b>. Reply <b>next</b> for another batch.</p>',
  );
  return {
    subject: header,
    html: parts.join('\n'),
    batch: { created_at: run.started_at, items: batch },
  };
})()
